import * as T from './three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {clone} from './vendor/SkeletonUtils.js';
export const WOLF_KEY='ordinary-mage-wolf-motions-v1';
export const WOLF_ASSET='assets/monsters/wolf-rig-edited.glb';
export const WOLF_RIG_VERSION='edited-20261111';
export const WOLF_ACTIONS=[['idle','대기'],['walk','걷기'],['run','달리기'],['windup','돌진 준비'],['attack','돌진'],['recover','공격 후 회복']];
let sourcePromise;
export class WolfRig{
 static async load(){sourcePromise??=new GLTFLoader().loadAsync(WOLF_ASSET).catch(e=>{sourcePromise=null;throw e;});const gltf=await sourcePromise;return new WolfRig(clone(gltf.scene));}
 constructor(model){this.group=new T.Group();this.model=model;this.group.add(model);this.bones=[];this.meshes=[];model.traverse(o=>{if(o.isBone)this.bones.push(o);if(o.isMesh){o.geometry=o.geometry.clone();o.material=Array.isArray(o.material)?o.material.map(m=>m.clone()):o.material.clone();o.frustumCulled=false;this.meshes.push(o);}});model.updateMatrixWorld(true);const box=new T.Box3().setFromObject(model),scale=1.5/box.getSize(new T.Vector3()).y;model.scale.multiplyScalar(scale);model.position.y-=box.min.y*scale;model.updateMatrixWorld(true);this.rest=this.bones.map(b=>({p:b.position.clone(),q:b.quaternion.clone(),s:b.scale.clone(),world:b.matrixWorld.clone()}));this.defaults=this.makeDefaults();}
 reset(){this.bones.forEach((b,i)=>{b.position.copy(this.rest[i].p);b.quaternion.copy(this.rest[i].q);b.scale.copy(this.rest[i].s);});}
 apply(rotations){this.reset();this.bones.forEach((b,i)=>{if(rotations[i])b.quaternion.multiply(new T.Quaternion().fromArray(rotations[i]));});this.group.updateMatrixWorld(true);for(const m of this.meshes)if(m.skeleton)m.skeleton.update();}
 sample(project,id,seconds){const a=project.actions.find(a=>a.id===id)||project.actions[0],max=a.frames-1;let frame=seconds*a.fps;frame=a.loop?((frame%max)+max)%max:Math.min(max,Math.max(0,frame));const keys=a.keys;let left=keys[0],right=keys.at(-1);for(let i=0;i<keys.length-1;i++)if(frame>=keys[i].frame&&frame<=keys[i+1].frame){left=keys[i];right=keys[i+1];break;}const t=right.frame===left.frame?0:T.MathUtils.clamp((frame-left.frame)/(right.frame-left.frame),0,1),smooth=t*t*(3-2*t);return this.bones.map((_,i)=>new T.Quaternion().fromArray(left.rotations[i]).slerp(new T.Quaternion().fromArray(right.rotations[i]),smooth).toArray());}
 makeDefaults(){const q=(i,angle)=>{const axis=new T.Vector3(1,0,0).applyQuaternion(new T.Quaternion().setFromRotationMatrix(new T.Matrix4().extractRotation(this.rest[i].world)).invert());return new T.Quaternion().setFromAxisAngle(axis,angle).toArray();};return {version:1,characterId:'wolf',rigVersion:WOLF_RIG_VERSION,bones:this.bones.map(b=>b.name),actions:WOLF_ACTIONS.map(([id,name])=>{const frames=['walk','run'].includes(id)?25:19,keys=[0,.25,.5,.75,1].map(t=>{const rotations=this.bones.map(()=>[0,0,0,1]);const set=(i,a)=>{if(i<this.bones.length)rotations[i]=q(i,a);};if(id==='walk'||id==='run'){const wave=Math.sin(t*Math.PI*2)*(id==='run'?.3:.18);for(const [i,sign]of [[11,1],[15,-1],[19,-1],[23,1]])set(i,wave*sign);for(const [i,sign]of [[12,1],[16,-1],[20,-1],[24,1]])set(i,Math.max(0,wave*sign)*.55);}else if(id==='windup'){set(9,Math.sin(t*Math.PI/2)*.16);set(11,-t*.12);set(15,-t*.12);}else if(id==='attack'){set(9,-Math.sin(t*Math.PI)*.18);set(11,-Math.sin(t*Math.PI)*.3);set(15,-Math.sin(t*Math.PI)*.3);}else if(id==='recover'){set(9,.12*(1-t));}else{set(9,Math.sin(t*Math.PI*2)*.025);}return {frame:Math.round(t*(frames-1)),rotations};});return {id,name,frames,fps:24,loop:['idle','walk','run'].includes(id),keys};})};}
 dispose(){for(const m of this.meshes){m.geometry.dispose();for(const mat of(Array.isArray(m.material)?m.material:[m.material]))mat.dispose();}}
}
export function validateWolfProject(p,rig){if(p?.characterId!=='wolf'||p.rigVersion!==WOLF_RIG_VERSION||JSON.stringify(p.bones)!==JSON.stringify(rig.bones.map(b=>b.name)))throw Error('이 늑대의 뼈 구조와 맞는 동작 파일을 선택하세요.');if(!Array.isArray(p.actions)||p.actions.length!==WOLF_ACTIONS.length)throw Error('필수 동작 6개가 필요합니다.');for(const [id]of WOLF_ACTIONS)if(p.actions.filter(a=>a.id===id).length!==1)throw Error('동작 종류가 중복되거나 빠졌습니다.');for(const a of p.actions){if(!Number.isInteger(a.frames)||a.frames<2||a.frames>240||!Number.isFinite(a.fps)||a.fps<1||a.fps>60||!Array.isArray(a.keys)||!a.keys.length||a.keys.length>240)throw Error('프레임 설정을 확인하세요.');const seen=new Set();for(const k of a.keys){if(!Number.isInteger(k.frame)||k.frame<0||k.frame>=a.frames||seen.has(k.frame)||!Array.isArray(k.rotations)||k.rotations.length!==rig.bones.length)throw Error('키프레임 형식이 맞지 않습니다.');seen.add(k.frame);for(const q of k.rotations){if(!Array.isArray(q)||q.length!==4||!q.every(Number.isFinite)||Math.abs(Math.hypot(...q)-1)>.01)throw Error('관절 회전 값이 올바르지 않습니다.');}}a.keys.sort((a,b)=>a.frame-b.frame);if(a.keys[0].frame!==0||a.keys.at(-1).frame!==a.frames-1)throw Error('첫 프레임과 마지막 프레임이 필요합니다.');}return p;}
let cachedRaw,cachedProject;
export function savedWolfProject(rig){try{const raw=localStorage.getItem(WOLF_KEY);if(raw!==cachedRaw){cachedRaw=raw;cachedProject=raw?validateWolfProject(JSON.parse(raw),rig):null;}return cachedProject||rig.defaults;}catch{return rig.defaults;}}
